--
-- Table structure for table `matter_communications`
--

CREATE TABLE `matter_communications` (
  `id` int(11) NOT NULL,
  `matter_id` int(11) NOT NULL,
  `type` varchar(50) DEFAULT 'Note',
  `subject` varchar(255) NOT NULL,
  `description` text DEFAULT NULL,
  `communication_date` datetime DEFAULT current_timestamp(),
  `contact_id` int(11) DEFAULT NULL,
  `document_ids` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL CHECK (json_valid(`document_ids`)),
  `created_by` int(11) DEFAULT NULL,
  `created_at` datetime DEFAULT current_timestamp(),
  `updated_at` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

